def trump_detector(s):
    vowels = {'a', 'e', 'i', 'o', 'u'}
    total_vowels = 0
    extra_vowels = 0
    i = 0
    n = len(s)

    while i < n:
        if s[i].lower() in vowels:
            total_vowels += 1
            current_char = s[i].lower()
            j = i + 1
